import{_ as c,C as n,o as h,c as o,j as e,a,E as t,a2 as i,w as d}from"./chunks/framework.B-bxTAy7.js";const u=JSON.parse('{"title":"03 · 嵌入式 C 与寄存器思维","description":"","frontmatter":{"title":"03 · 嵌入式 C 与寄存器思维"},"headers":[],"relativePath":"embedded/embedded-c.md","filePath":"embedded/embedded-c.md","lastUpdated":1792416913000}'),g={name:"embedded/embedded-c.md"};function k(x,s,y,E,A,b){const l=n("Meta"),p=n("Prereq"),m=n("BitManipDemo"),r=n("DemoBox");return h(),o("div",null,[s[4]||(s[4]=e("h1",{id:"_03-·-嵌入式-c-与寄存器思维",tabindex:"-1"},[a("03 · 嵌入式 C 与寄存器思维 "),e("a",{class:"header-anchor",href:"#_03-·-嵌入式-c-与寄存器思维","aria-label":'Permalink to "03 · 嵌入式 C 与寄存器思维"'},"​")],-1)),t(l,{time:"40 min",level:"核心",note:"寄存器就是有地址的内存，位操作是基本功，volatile 和原子性是分水岭"}),e("p",null,[s[0]||(s[0]=a("本章的第一个概念——寄存器为什么就是内存——单独抽成了卡片：",-1)),t(p,{id:"register-map"}),s[1]||(s[1]=a("。",-1))]),s[5]||(s[5]=i('<h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li><strong>寄存器 = 占据固定地址的一小块内存</strong>。所谓「配置外设」，本质就是往这些地址里写特定的数；C 语言里用指针（通常是厂家定义好的结构体指针）访问它们。</li><li><strong>位操作只有四个动作</strong>：置位 <code>|= (1&lt;&lt;n)</code>、清零 <code>&amp;= ~(1&lt;&lt;n)</code>、翻转 <code>^= (1&lt;&lt;n)</code>、读位 <code>(reg&gt;&gt;n)&amp;1</code>。<strong>清零必须取反</strong>，直接 <code>&amp;= (1&lt;&lt;n)</code> 是经典错误。</li><li><strong><code>volatile</code> 告诉编译器「这个变量会被你不知道的方式改变，别优化掉对它的读写」</strong>。硬件寄存器、中断里改的全局变量、RTOS 共享变量，三者都必须加。</li><li><strong>改寄存器的某一位要用「读—改—写」，但这不是原子的</strong>；STM32 提供 <code>BSRR</code> 寄存器实现单条指令的原子位操作。</li><li><strong>嵌入式 C 的额外纪律</strong>：慎用 <code>malloc</code>、注意结构体对齐、全局/静态变量要算进 RAM、<code>const</code> 常量放 Flash。</li></ol><h2 id="一、内存映射-寄存器是有地址的内存" tabindex="-1">一、内存映射：寄存器是有地址的内存 <a class="header-anchor" href="#一、内存映射-寄存器是有地址的内存" aria-label="Permalink to &quot;一、内存映射：寄存器是有地址的内存&quot;">​</a></h2>',3)),e("p",null,[s[2]||(s[2]=a("完整的地址空间划分与偏移表见 ",-1)),t(p,{id:"register-map"}),s[3]||(s[3]=a("；下面先看它长什么样。",-1))]),s[6]||(s[6]=i(`<p>Cortex-M 有 4 GB 的线性地址空间（32 位地址），芯片厂商把它切成几块：</p><table tabindex="0"><thead><tr><th>地址区间</th><th>放什么</th></tr></thead><tbody><tr><td><code>0x0000 0000</code> ~</td><td>代码区（Flash 的别名，实际从 <code>0x0800 0000</code> 开始）</td></tr><tr><td><code>0x0800 0000</code> ~</td><td><strong>Flash</strong>：程序代码和 <code>const</code> 常量</td></tr><tr><td><code>0x2000 0000</code> ~</td><td><strong>SRAM</strong>：全局变量、栈、堆</td></tr><tr><td><code>0x4000 0000</code> ~</td><td><strong>外设寄存器</strong>（APB1 / APB2 / AHB 各总线挂的外设）</td></tr><tr><td><code>0xE000 0000</code> ~</td><td>Cortex-M 内核的系统控制块（NVIC、SysTick 等）</td></tr></tbody></table><p>以 F103 为例，GPIOA 的寄存器组从 <code>0x4001 0800</code> 开始，内部按固定偏移排列：</p><table tabindex="0"><thead><tr><th>偏移</th><th>寄存器</th><th>作用</th></tr></thead><tbody><tr><td><code>0x00</code></td><td><code>CRL</code></td><td>配置 Pin0~7（每脚 4 位）</td></tr><tr><td><code>0x04</code></td><td><code>CRH</code></td><td>配置 Pin8~15（每脚 4 位）</td></tr><tr><td><code>0x08</code></td><td><code>IDR</code></td><td>输入数据（读引脚电平）</td></tr><tr><td><code>0x0C</code></td><td><code>ODR</code></td><td>输出数据（写引脚电平）</td></tr><tr><td><code>0x10</code></td><td><code>BSRR</code></td><td><strong>原子</strong>置位/清零</td></tr><tr><td><code>0x14</code></td><td><code>BRR</code></td><td>清零（等价于 BSRR 高 16 位）</td></tr></tbody></table><p>CMSIS 库把这些地址定义成一个结构体指针，于是你可以写：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GPIOA_BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40010800</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UL</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  volatile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CRL, CRH, IDR, ODR, BSRR, BRR, LCKR;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} GPIO_TypeDef;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> GPIOA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((GPIO_TypeDef </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)GPIOA_BASE)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPIOA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ODR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 就是往 0x4001080C 这个地址写</span></span></code></pre></div><p><strong>这一点想通了，后面所有外设就都通了</strong>：UART 的 <code>DR</code> 寄存器、定时器的 <code>CNT</code>、ADC 的 <code>DR</code>，全都是「有名字的地址」，操作它们就是读写内存。</p><h2 id="二、位操作的四个动作" tabindex="-1">二、位操作的四个动作 <a class="header-anchor" href="#二、位操作的四个动作" aria-label="Permalink to &quot;二、位操作的四个动作&quot;">​</a></h2><p>外设寄存器几乎从不「整个赋值」——因为一个 32 位寄存器里往往塞了十几个互不相关的配置字段，你只想改其中一位，绝不能动其他位。于是有了四个标准动作：</p><table tabindex="0"><thead><tr><th>动作</th><th>写法</th><th>含义</th></tr></thead><tbody><tr><td><strong>置位</strong>（把某位写成 1）</td><td><code>reg |= (1 &lt;&lt; n)</code></td><td>OR 上「只有第 n 位为 1」的掩码，其余位不变</td></tr><tr><td><strong>清零</strong>（把某位写成 0）</td><td><code>reg &amp;= ~(1 &lt;&lt; n)</code></td><td>AND 上「只有第 n 位为 0」的掩码</td></tr><tr><td><strong>翻转</strong>（1↔0）</td><td><code>reg ^= (1 &lt;&lt; n)</code></td><td>异或，同掩码翻转两次回到原值</td></tr><tr><td><strong>读位</strong></td><td><code>(reg &gt;&gt; n) &amp; 1</code></td><td>右移到最低位再屏蔽其余位</td></tr></tbody></table>`,10)),t(r,{title:"位操作演练台：点选寄存器位，亲手做一遍置位/清零/翻转/读位",hint:"先载入 0x00A0，再依次做：置位 bit3 → 清零 bit5 → 翻转 bit7，看十六进制和二进制怎么变。特别注意「清零」为什么必须先取反。"},{default:d(()=>[t(m)]),_:1}),s[7]||(s[7]=i(`<div class="tip custom-block"><p class="custom-block-title">例 1 · 置位：把寄存器第 3 位写成 1</p><p>寄存器初值 <code>0x0000 00A0</code>（二进制 <code>1010 0000</code>，即 bit5 和 bit7 为 1）。要把 <strong>bit3</strong> 置 1：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>0x00A0</mtext><mtext>  </mtext><mi mathvariant="normal">∣</mi><mtext>  </mtext><mo stretchy="false">(</mo><mn>1</mn><mo>≪</mo><mn>3</mn><mo stretchy="false">)</mo><mo>=</mo><mtext>0x00A0</mtext><mtext>  </mtext><mi mathvariant="normal">∣</mi><mtext>  </mtext><mtext>0x0008</mtext><mo>=</mo><mtext>0x00A8</mtext></mrow><annotation encoding="application/x-tex">\\text{0x00A0} \\;|\\; (1 \\ll 3) = \\text{0x00A0} \\;|\\; \\text{0x0008} = \\text{0x00A8} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">0x00A0</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">3</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">0x00A0</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord text"><span class="mord">0x0008</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">0x00A8</span></span></span></span></span></span><p>二进制：<code>1010 0000</code> → <code>1010 1000</code>，bit5、bit7 原封不动。这就是 OR 的性质：任何位 OR 0 保持不变，OR 1 变成 1。</p></div><div class="tip custom-block"><p class="custom-block-title">例 2 · 清零：把第 5 位写成 0（最易错的一步）</p><p>承接上一步的 <code>0x00A8</code>，要把 <strong>bit5</strong> 清 0。</p><p><strong>正确做法</strong>——掩码取反：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>0x00A8</mtext><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mo>∼</mo><mo stretchy="false">(</mo><mn>1</mn><mo>≪</mo><mn>5</mn><mo stretchy="false">)</mo><mo>=</mo><mtext>0x00A8</mtext><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mtext>0xFFFF FFDF</mtext><mo>=</mo><mtext>0x0088</mtext></mrow><annotation encoding="application/x-tex">\\text{0x00A8} \\; \\&amp; \\; \\sim(1 \\ll 5) = \\text{0x00A8} \\; \\&amp; \\; \\text{0xFFFF FFDF} = \\text{0x0088} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">0x00A8</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">5</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">0x00A8</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord text"><span class="mord">0xFFFF FFDF</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord text"><span class="mord">0x0088</span></span></span></span></span></span><p><strong>错误做法</strong>（初学者高频）——忘了取反：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>0x00A8</mtext><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mo stretchy="false">(</mo><mn>1</mn><mo>≪</mo><mn>5</mn><mo stretchy="false">)</mo><mo>=</mo><mtext>0x00A8</mtext><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mtext>0x20</mtext><mo>=</mo><mtext>0x0020</mtext></mrow><annotation encoding="application/x-tex">\\text{0x00A8} \\; \\&amp; \\; (1 \\ll 5) = \\text{0x00A8} \\; \\&amp; \\; \\text{0x20} = \\text{0x0020} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">0x00A8</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">5</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">0x00A8</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord text"><span class="mord">0x20</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord text"><span class="mord">0x0020</span></span></span></span></span></span><p>结果是除了 bit5 之外<strong>所有位都被清掉</strong>了，整个寄存器被毁。记住口诀：<strong>置位用原掩码，清零用反掩码</strong>。</p></div><div class="tip custom-block"><p class="custom-block-title">例 3 · 翻转与读位</p><p>承接 <code>0x0088</code>，翻转 <strong>bit7</strong>：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>0x0088</mtext><mtext>  </mtext><mo>⊕</mo><mtext>  </mtext><mo stretchy="false">(</mo><mn>1</mn><mo>≪</mo><mn>7</mn><mo stretchy="false">)</mo><mo>=</mo><mtext>0x0088</mtext><mtext>  </mtext><mo>⊕</mo><mtext>  </mtext><mtext>0x80</mtext><mo>=</mo><mtext>0x0008</mtext></mrow><annotation encoding="application/x-tex">\\text{0x0088} \\; \\oplus \\; (1 \\ll 7) = \\text{0x0088} \\; \\oplus \\; \\text{0x80} = \\text{0x0008} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord">0x0088</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊕</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">7</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord text"><span class="mord">0x0088</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⊕</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord text"><span class="mord">0x80</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord text"><span class="mord">0x0008</span></span></span></span></span></span><p>bit7 从 1 变成 0。翻转的性质是<strong>可逆</strong>：再执行一次 <code>^= (1&lt;&lt;7)</code> 又会变回 <code>0x0088</code>，所以 <code>LED_Toggle</code> 这类操作用异或最自然。</p><p><strong>读位</strong>：读当前值 <code>0x0008</code> 的 bit5：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mo stretchy="false">(</mo><mn>0</mn><mtext>x</mtext><mn>0008</mn><mo>≫</mo><mn>5</mn><mo stretchy="false">)</mo><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mn>1</mn><mo>=</mo><mn>0</mn><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mn>1</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">(0\\text{x}0008 \\gg 5) \\; \\&amp; \\; 1 = 0 \\; \\&amp; \\; 1 = 0 </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">0</span><span class="mord text"><span class="mord">x</span></span><span class="mord">0008</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≫</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">5</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span></span><p>即 bit5 当前是 0。注意读位时<strong>先移位再屏蔽</strong>的顺序不能颠倒——若写成 <code>reg &amp; (1&lt;&lt;5)</code>，得到的会是 <code>0x00</code> 或 <code>0x20</code>，而不是干净的 0/1。</p></div><div class="tip custom-block"><p class="custom-block-title">例 4 · 写多位的配置字段（位域写入）</p><p>配置 GPIO 时，每个引脚占 <strong>4 位</strong>（2 位模式 + 2 位速度）。要把 <code>0x00A0</code> 的 <strong>bit[3:2]</strong> 这个两位的字段改写成 <code>01</code>，不能只清零再置位，得<strong>先把整个字段抹掉，再写入新值</strong>：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mask </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 0b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">11</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              // 字段掩码：bit[3:2]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reg </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (reg </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mask) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">0b</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">01</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // 先清空字段，再写入值</span></span></code></pre></div><p>代入验证：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>0x00A0</mtext><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mo>∼</mo><mn>0</mn><mtext>x0C</mtext><mo>=</mo><mtext>0x00A0</mtext><mtext>  </mtext><mi mathvariant="normal">&amp;</mi><mtext>  </mtext><mtext>0xFFFF FFF3</mtext><mo>=</mo><mtext>0x00A0</mtext></mrow><annotation encoding="application/x-tex">\\text{0x00A0} \\; \\&amp; \\; \\sim 0\\text{x0C} = \\text{0x00A0} \\; \\&amp; \\; \\text{0xFFFF FFF3} = \\text{0x00A0} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">0x00A0</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0</span><span class="mord text"><span class="mord">x0C</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">0x00A0</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">&amp;</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord text"><span class="mord">0xFFFF FFF3</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">0x00A0</span></span></span></span></span></span><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>0x00A0</mtext><mtext>  </mtext><mi mathvariant="normal">∣</mi><mtext>  </mtext><mo stretchy="false">(</mo><mn>1</mn><mo>≪</mo><mn>2</mn><mo stretchy="false">)</mo><mo>=</mo><mtext>0x00A4</mtext></mrow><annotation encoding="application/x-tex">\\text{0x00A0} \\; | \\; (1 \\ll 2) = \\text{0x00A4} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">0x00A0</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≪</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">2</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">0x00A4</span></span></span></span></span></span><p>结果 <code>0x00A4</code>，其中 bit[3:2] = <code>01</code>（因为 <code>0xA4 = 1010 0100</code>，bit3=0、bit2=1）。</p><p><strong>为什么不能分两步</strong>（先 <code>|= (1&lt;&lt;2)</code> 再 <code>&amp;= ~(1&lt;&lt;3)</code>）？在单线程里结果相同，但如果中间被中断打断，硬件会短暂看到一个<strong>中间态</strong>（字段先变成 <code>11</code> 之类），对配置敏感的寄存器（如时钟分频）可能引发故障。所以配字段要<strong>一次算好一次写入</strong>。</p></div><h2 id="三、volatile-别让编译器把你的代码优化没了" tabindex="-1">三、<code>volatile</code>：别让编译器把你的代码优化没了 <a class="header-anchor" href="#三、volatile-别让编译器把你的代码优化没了" aria-label="Permalink to &quot;三、\`volatile\`：别让编译器把你的代码优化没了&quot;">​</a></h2><p>编译器会做一件很聪明的事：如果一个变量在某段代码里没被写过，它就认为这个值不会变，把重复读取优化掉。在 PC 上这没问题，但在嵌入式里，<strong>有些变量会被编译器看不见的东西改变</strong>——硬件、中断、另一个任务。</p><p>三种必须加 <code>volatile</code> 的场景：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ① 硬件寄存器（CMSIS 的结构体成员全部带 volatile）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((USART1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { }</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 等待发送完成标志</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ② 中断服务程序里修改的标志</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">volatile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint8_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> flag </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HAL_GPIO_EXTI_Callback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint16_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> pin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { flag </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flag) { }</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* ... */</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ③ RTOS / 多线程共享的变量</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">volatile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tick_count;</span></span></code></pre></div><p><strong>不加 <code>volatile</code> 会发生什么</strong>：<code>while(!flag);</code> 里，编译器发现循环体不修改 <code>flag</code>，就把它优化成「读一次到寄存器，然后死循环」——<strong>中断明明把 flag 置 1 了，主循环却永远看不到</strong>。这类 bug 极其隐蔽：开优化（<code>-O2</code>）才出现，关优化（<code>-O0</code>）一切正常。</p><p><strong><code>volatile</code> 不保证什么</strong>：它只保证「每次都真的去内存读/写」，<strong>不保证原子性</strong>，也不能替代互斥锁。多字节变量的跨任务保护要靠关中断或 RTOS 的同步机制。</p><h2 id="四、原子性-bsrr-为什么存在" tabindex="-1">四、原子性：<code>BSRR</code> 为什么存在 <a class="header-anchor" href="#四、原子性-bsrr-为什么存在" aria-label="Permalink to &quot;四、原子性：\`BSRR\` 为什么存在&quot;">​</a></h2><p>看这行很常见的代码：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPIOA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ODR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 看起来是「只改 bit5」</span></span></code></pre></div><p>它编译后其实是三步机器操作：<strong>读 ODR → 或运算 → 写回 ODR</strong>。如果在这三步之间来了个中断，中断里也改了 ODR 的其他位，那么中断返回后，主程序写回的旧值会把中断的修改<strong>覆盖掉</strong>。</p><p>STM32 为此提供了 <code>BSRR</code>（Bit Set/Reset Register）：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPIOA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BSRR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // 低 16 位：置位 → bit5 = 1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GPIOA</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BSRR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 高 16 位：清零 → bit5 = 0</span></span></code></pre></div><p><strong>写入 BSRR 是一次写操作</strong>，硬件内部完成置位/清零，不存在「读—改—写」的窗口，因此是原子的——中断里改 GPIO 可以放心用。</p><blockquote><p>这也是 HAL 库 <code>HAL_GPIO_WritePin</code> 内部用 BSRR/BRR 而不是 <code>ODR |=</code> 的原因之一。</p></blockquote><h2 id="五、嵌入式-c-的额外纪律" tabindex="-1">五、嵌入式 C 的额外纪律 <a class="header-anchor" href="#五、嵌入式-c-的额外纪律" aria-label="Permalink to &quot;五、嵌入式 C 的额外纪律&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>纪律</th><th>原因</th></tr></thead><tbody><tr><td><strong>动态内存</strong></td><td>尽量不用 <code>malloc</code> / <code>free</code></td><td>内存碎片；失败时难以恢复；确定性差</td></tr><tr><td><strong>栈</strong></td><td>大数组不要放函数内；递归要谨慎</td><td>栈溢出会静默破坏内存，且默认栈可能只有几 KB</td></tr><tr><td><strong>结构体对齐</strong></td><td>与硬件/协议对应的结构体要检查对齐</td><td>编译器会插填充字节，导致结构体大小和成员偏移与预期不符</td></tr><tr><td><strong><code>const</code></strong></td><td>常量表加 <code>const</code></td><td>会被放进 Flash 而不是占用宝贵的 RAM</td></tr><tr><td><strong><code>static</code></strong></td><td>限制作用域，避免全局污染</td><td>也便于编译器优化</td></tr><tr><td><strong>浮点</strong></td><td>M0/M3 无 FPU，<code>float</code> 运算是软件模拟，很慢</td><td>需要浮点运算选 M4 或改用定点</td></tr></tbody></table><p>结构体对齐的例子：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">typedef</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  uint8_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  a;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 偏移 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 偏移 4（编译器插了 3 字节填充）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  uint8_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  c;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   // 偏移 8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} Bad;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          // sizeof = 12，不是 6</span></span></code></pre></div><p>按成员从大到小排列，或用 <code>__attribute__((packed))</code>（但会带来非对齐访问的性能损失甚至硬件错误）来消除填充。</p><h2 id="六、工程实例" tabindex="-1">六、工程实例 <a class="header-anchor" href="#六、工程实例" aria-label="Permalink to &quot;六、工程实例&quot;">​</a></h2><p><strong>为什么 HAL 库的 handle 里到处是 <code>volatile</code></strong>：打开 <code>stm32f1xx_hal_uart.h</code>，你会看到 <code>UART_HandleTypeDef</code> 里的状态成员带 <code>__IO</code>（就是 <code>volatile</code> 的宏）。因为 UART 的收发状态会被中断服务程序修改，主程序轮询它时必须每次真正读内存。</p><p><strong>一个真实的隐蔽 bug</strong>：某项目用 <code>while(!tx_done);</code> 等待 DMA 发送完成，<code>tx_done</code> 在 DMA 中断里置位。Debug 版本（<code>-O0</code>）正常，Release（<code>-O2</code>）死机。原因就是 <code>tx_done</code> 没加 <code>volatile</code>，被优化成了只读一次。加上 <code>volatile</code> 后两个版本都正常——<strong>这类问题只在优化后才暴露，所以要尽早用 Release 配置编译验证</strong>。</p><h2 id="七、易错清单-自检" tabindex="-1">七、易错清单 + 自检 <a class="header-anchor" href="#七、易错清单-自检" aria-label="Permalink to &quot;七、易错清单 + 自检&quot;">​</a></h2><ul><li>[ ] <strong>清零忘了取反</strong>：<code>&amp;= ~(1&lt;&lt;n)</code> 才是清零，<code>&amp;= (1&lt;&lt;n)</code> 会毁掉整个寄存器</li><li>[ ] <strong>读位顺序</strong>：<code>(reg &gt;&gt; n) &amp; 1</code>，先移位后屏蔽</li><li>[ ] <strong>改多位字段</strong>：先 <code>&amp; ~mask</code> 清空，再 <code>| value</code> 一次写入</li><li>[ ] <strong>中断/RTOS 共享的变量没加 <code>volatile</code></strong>：不优化时正常，开 <code>-O2</code> 后死等</li><li>[ ] <strong><code>volatile</code> 不等于原子</strong>：多字节共享变量仍需关中断或用 RTOS 同步</li><li>[ ] <strong>中断里改 GPIO 用 <code>ODR |=</code></strong>：有读—改—写竞态，改用 <code>BSRR</code></li><li>[ ] <strong>函数里开大数组导致栈溢出</strong>：改成 <code>static</code> 或全局</li><li>[ ] <strong>结构体直接映射到硬件/协议</strong>：务必检查对齐和填充</li></ul><p><strong>自检</strong>：写出「把 32 位寄存器 <code>reg</code> 的 bit7 清零、bit3 置位、其余位不变」的两种写法（普通写法 + BSRR 原子写法）；并说出 <code>volatile</code> 必须用的三个场景。（答案：<code>reg = (reg &amp; ~(1&lt;&lt;7)) | (1&lt;&lt;3);</code>；<code>GPIOx-&gt;BSRR = (1&lt;&lt;(7+16)) | (1&lt;&lt;3);</code>；硬件寄存器、中断修改的变量、多任务共享变量）</p>`,29))])}const D=c(g,[["render",k]]);export{u as __pageData,D as default};
